questiontext.text:
Analiza la siguiente implementación de Fibonacci e indica a qué clase de complejidad pertenece
```c
unsigned long long fibonacci(int n) {
  if (n <= 1) {
    return n;
  }
  unsigned long long a = 0, b = 1, temp;
  for (int i = 2; i <= n; i++) {
    temp = a + b;
    a = b;
    b = temp;
  }
  return b;
}
```
¿Cuál es la complejidad temporal y espacial de este algoritmo? Justifica tu respuesta.

Analiza el siguiente fragmento de código y determina su orden de complejidad (Big O).
_Asuman que la función `printf` tiene un costo de `1`_
```c
void funcion(int n) {
  int suma = 0;
  for (int i = 1; i <= n; i++) {
    suma = suma + i;
  }
  printf("%d", suma);
}
```

Determina el orden de complejidad (Big O) del siguiente fragmento de código.
_Asuman que la función `printf` tiene un costo de `1`_
```c
void funcion(int n) {
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      printf("%d ", i * j);
    }
  }
}
```

Determina la complejidad temporal (Big O) del siguiente algoritmo.
_Asuman que la función `printf` tiene un costo de `1`_
```c
void funcion(int n) {
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= i; j++) {
      for (int k = 1; k <= j; k++) {
        printf("%d ", i * j * k);
      }
    }
  }
}
```

Analiza el siguiente algoritmo e identifica su complejidad temporal (Big O).
```c
int funcion(int arr[], int l, int r, int x) {
  if (r >= l) {
    int mid = l + (r - l) / 2;
    if (arr[mid] == x) {
      return mid;
    }
    if (arr[mid] > x) {
      return funcion(arr, l, mid - 1, x);
    }
    return funcion(arr, mid + 1, r, x);
  }
  return -1;
}
```

Analiza la complejidad temporal (Big O) de la siguiente función recursiva.
```c
int funcion(int n) {
  if (n <= 1) {
    return n;
  }
  return funcion(n - 1) + funcion(n - 2);
}
```

¿Cuál es la complejidad temporal de la siguiente implementación de Fibonacci?
```
int fibonacci(int *fib, int n) {
  fib[0] = 0;
  fib[1] = 1;
  for (int i = 2; i <= n; i++) {
    fib[i] = fib[i - 1] + fib[i - 2];
  }
  return fib[i];
}
```

¿Cuál es la complejidad espacial de la siguiente implementación de Fibonacci?
```
int fibonacci(int *fib, int n) {
  fib[0] = 0;
  fib[1] = 1;
  int i = 2;
  for (; i <= n; i++) {
    fib[i] = fib[i - 1] + fib[i - 2];
  }
  return fib[i];
}
```
